		classification = 4101001,
		id = 410100104,
		icon = "10640",
		offset_y = 0,
		dec = "而且那次哗变的是一个步兵班的十人，如果进行突击只能从楼顶的天窗进入。"
	},
	[410100105] = {
		expression = "aichou",
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100105,
		icon = "10640",
		offset_y = 0,
		dec = "但是天窗下面就是有人质与劫匪的房间，从天窗索降会让突击队员暴露在劫匪的火力下。"
	},
	[410100106] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100106,
		icon = "10640",
		offset_y = 0,
		dec = "他们还要求停止边境冲突，保障其家人的安全，联邦军从现有防线后撤五公里，并且要求提供一辆装甲车供其撤离。"
	},
	[410100107] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100107,
		icon = "10640",
		offset_y = 0,
		dec = "我思索了一下，就对当地警督提出了要求。"
	},
	[410100108] = {
		expression = "aichou",
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100108,
		icon = "10640",
		offset_y = 0,
		dec = "让我进去，我要充当人质把那个儿童交换出来。"
	},
	[410100109] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100109,
		icon = "10640",
		offset_y = 0,
		dec = "因为普通的哗变士兵不会提出这么多无关要求的，这其中肯定有人工智能的指使。用我作为诱饵绝对会让那个混杂在人中的人工智能上当。"
	},
	[410100110] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100110,
		icon = "10640",
		offset_y = 0,
		dec = "身为圣殿之盾，身为一名学员，如果在对抗人工智能的战场上缺席，那就是我的失职！"
	},
	[410100111] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101001,
		id = 410100111,
		icon = "10640",
		offset_y = 0,
		dec = "班长，要是你的话，你会怎么办？"
	},
	[410100201] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101002,
		id = 410100201,
		icon = "10640",
		offset_y = 0,
		dec = "班长，别光顾着做菜。你也过来吃一点吧。"
	},
	[410100202] = {
