		offset_x = 0,
		showName = "旁白",
		speaker = "R",
		background = "dorm",
		classification = 4101002,
		id = 410100202,
		offset_y = 0,
		dec = "我只好放下锅铲，坐在了康茨坦丝对面。不这么做的话，估计又要饱受她的大道理轰炸了。"
	},
	[410100203] = {
