		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101002,
		id = 410100203,
		icon = "10640",
		offset_y = 0,
		dec = "班长，这次去耶梦加得十二区的桥之都，我去军事学院参观了哦。"
	},
	[410100204] = {
		background = "dorm",
		skip = 1,
