		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101002,
		id = 410100204,
		icon = "10640",
		offset_y = 0,
		dec = "算了，班长你就不用向我解释了哦，看你的表情我就知道似乎这段时光对你而言并不美好，你就不用强迫自己了。"
	},
	[410100205] = {
