		background = "dorm",
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101002,
		id = 410100205,
		icon = "10640",
		offset_y = 0,
		dec = "确实，这所人才辈出的军官摇篮非常吸引我呢！9世纪耶梦加得十二区乃至全世界最杰出的军事家与战略家都从这里毕业。"
	},
	[410100206] = {
