		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101002,
		id = 410100206,
		icon = "10640",
		offset_y = 0,
		dec = "不过我想，未来的一百年，将会是魂器学院的时代啊！"
	},
	[410100207] = {
		expression = "kaixin",
		background = "dorm",
		skip = 1,
