		speaker = "R",
		actorsoulid = 10,
		classification = 4101002,
		id = 410100208,
		icon = "10640",
		offset_y = 0,
		dec = "班长，您不是没有拿到军事学院的毕业证吗？不过现在，有一张含金量更高的毕业证等着你哦~"
