		offset_x = 0,
		showName = "旁白",
		speaker = "R",
		background = "dorm",
		classification = 4101004,
		id = 410100401,
		offset_y = 0,
		dec = "从伊文捷琳的房间里出来之后，我又到了康茨坦丝的房间里。"
