		actorsoulid = 10,
		classification = 4101004,
		id = 410100402,
		icon = "10640",
		offset_y = 0,
		dec = "班长，你来了。我想你是要谈关于这次度假的事吧。没错——的确是我让伊文捷琳穿泳衣的。"
