		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100403,
		icon = "10640",
		offset_y = 0,
		dec = "唉……我也只是想锻炼一下她的心理承受能力啊。伊文捷琳有两个缺点，一个是过于温柔，另一个就是，没有主见，优柔寡断。"
