		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100404,
		icon = "10640",
		offset_y = 0,
		dec = "她要是能迅速克服心理障碍穿上泳衣自然是最好的，但是如果她能果断拒绝我也会很开心，这说明她缺乏主见的毛病治好了。"
	},
	[410100405] = {
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100405,
		icon = "10640",
		offset_y = 0,
		dec = "班长我们讨论一些不那么严肃的事情吧。\n班长，我向你推荐我这次去的巴哈姆特一区海滩。"
	},
	[410100406] = {
		expression = "aichou",
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100406,
		icon = "10640",
		offset_y = 0,
		dec = "什么？度假的事怎么能如此儿戏呢！班长，人是需要劳逸结合的！班长，我觉得这一点你就需要好好向我学习了。"
	},
	[410100407] = {
