		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100407,
		icon = "10640",
		offset_y = 0,
		dec = "别看我平时工作的时候这么严肃，但每当度假的时候我都是玩得最尽兴的一个哦。"
	},
	[410100408] = {
		expression = "kaixin",
		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100408,
		icon = "10640",
		offset_y = 0,
		dec = "还是回到巴哈姆特一区海滩吧，我躺着气垫床飘荡在海面上。海滨刮着柔和的海风，真的很惬意呢。"
	},
	[410100409] = {
