		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100409,
		icon = "10640",
		offset_y = 0,
		dec = "那个时候我可以什么都不想，忘记自己还未完成的工作和任务，就这样躺在气垫床上飘。"
