		background = "dorm",
		skip = 1,
		offset_x = 0,
		showName = "康茨坦丝",
		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100410,
		icon = "10640",
		offset_y = 0,
		dec = "只有恢复了充足的精神，才能面对各种挑战哦。班长，你太不会自我放松了！心理健康状态绝对不好！"
