		speaker = "R",
		actorsoulid = 10,
		classification = 4101004,
		id = 410100411,
		icon = "10640",
		offset_y = 0,
		dec = "你也应该找个时间放个假啦，学院这边有我和院长，不会有什么问题的啦。但要是班长出了问题，那才是给我们添麻烦咯~"
	},
	[410100501] = {
