		background = "dorm",
		classification = 4101005,
		id = 410100501,
		icon = "10640",
		offset_y = 0,
		dec = "康茨坦丝举起水瓶，“咕嘟咕嘟”地喝完了整整一瓶矿泉水。"
	},
	[410100502] = {
