		actorsoulid = 10,
		classification = 4101005,
		id = 410100505,
		icon = "10640",
		offset_y = 0,
		dec = "拿这次和三区空勤部队的会议来说吧，演习计划要他们配合我们对攻击目标进行破坏行动。可是我们连对方能做到什么都搞不清楚。"
